import {$,escapeHTML as esc,icon} from './ui.js?v=13';
import {createPublisherClient} from './publisher-client.js?v=1';
const helpers=()=>import('./publisher-import.js?v=3');
const publisherIcon=name=>icon(name);
export function createPublisher(ctx){
 const api=createPublisherClient();let signedIn=false,busy=false,books=[],draft=null,parts=[],prepared=null,recovery=!!globalThis.location?.hash.includes('type=recovery');
 const tr=(en,id)=>ctx.language()==='id'?id:en;
 const msg=(text,error=false)=>{const el=$('#publisher-message');if(el){const content=el.querySelector('.publisher-message-text');if(content)content.textContent=text;else el.textContent=text;el.hidden=!text;el.dataset.error=String(error);el.setAttribute('role',error?'alert':'status');const symbol=el.querySelector('.publisher-message-symbol');if(symbol)symbol.innerHTML=icon(error?'info':'check');}};
 document.addEventListener('pointerdown',event=>{if(event.target.closest?.('[data-action=publisher-toggle-password]'))event.preventDefault();});
 const emptyBook=()=>({id:'',title:'',author:'',synopsis:'',language:'id',status:'ongoing',is_published:true,cover_url:null});
 const nextDate=()=>{const d=new Date();d.setDate(d.getDate()+1);d.setHours(19,0,0,0);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
 function loginView(){return `<div class="publisher-auth-shell"><form id="publisher-login-form" class="glass publisher-card publisher-form publisher-auth-card" novalidate>
 <div class="publisher-auth-heading"><span class="publisher-auth-emblem">${icon('edit')}</span><div><h2>${tr('Sign in','Masuk')}</h2><p>${tr('Manage your stories.','Kelola ceritamu.')}</p></div></div>
 <div class="publisher-auth-field"><label for="publisher-email">Email</label><div class="publisher-input">${publisherIcon('mail')}<input id="publisher-email" type="email" autocomplete="username" inputmode="email" autocapitalize="off" spellcheck="false" maxlength="320" placeholder="name@example.com"></div></div>
 <div class="publisher-auth-field"><div class="publisher-field-heading"><label for="publisher-password">${tr('Password','Kata sandi')}</label><button class="publisher-text-button" type="button" data-action="publisher-recover">${tr('Forgot password?','Lupa kata sandi?')}</button></div><div class="publisher-input">${icon('lock')}<input id="publisher-password" type="password" autocomplete="current-password" minlength="8" placeholder="${tr('Enter your password','Masukkan kata sandi')}"><button class="publisher-password-toggle" type="button" data-action="publisher-toggle-password" data-for="publisher-password" aria-label="${tr('Show password','Tampilkan kata sandi')}" aria-pressed="false">${publisherIcon('eye')}</button></div></div>
 <button class="primary publisher-sign-in" type="submit"><span>${tr('Sign in','Masuk')}</span>${icon('arrow')}</button>
 <div class="publisher-auth-footer"><span>${tr('First time here?','Baru pertama kali?')}</span><button class="publisher-text-button" type="button" data-action="publisher-signup">${tr('Create account','Buat akun')}</button></div>
 </form><details class="publisher-key-access"><summary>${icon('lock')}<span>${tr('Use a publisher key','Gunakan publisher key')}</span>${icon('chevron')}</summary><form id="publisher-key-form" class="publisher-form" novalidate><label>Publisher key<input id="publisher-key" type="password" autocomplete="off" autocapitalize="off" spellcheck="false"></label><button class="secondary" type="submit">${tr('Connect','Hubungkan')}</button></form></details><p class="publisher-access-note">${tr('Publisher access is reserved for the owner.','Akses publisher khusus pemilik.')}</p></div>`;}
 function dashboard(){return `<section class="publisher-dashboard"><div class="publisher-toolbar"><button class="primary publisher-upload" data-action="publisher-upload">${icon('upload')}<span>${tr('Upload EPUB','Unggah EPUB')}</span></button><div class="publisher-toolbar-actions"><button class="icon-button" data-action="publisher-refresh" aria-label="${tr('Refresh books','Segarkan buku')}">${icon('refresh')}</button><button class="icon-button" data-action="publisher-logout" aria-label="${tr('Sign out','Keluar')}">${publisherIcon('logout')}</button></div></div>
 <section class="glass publisher-library"><div class="publisher-library-heading"><h2>${tr('Books','Buku')}</h2><span class="publisher-book-count">${books.length}</span></div><div class="publisher-book-list">${books.length?books.map(book=>`<article class="publisher-book-row"><div class="publisher-book-info"><h3>${esc(book.title)}</h3><div class="publisher-book-meta"><span class="publisher-status-badge" data-status="${book.status}">${book.status==='completed'?tr('Completed','Tamat'):tr('Ongoing','Bersambung')}</span><span class="publisher-visibility" data-published="${book.is_published}"><i aria-hidden="true"></i>${book.is_published?tr('Published','Terbit'):tr('Draft','Draf')}</span></div></div><div class="publisher-book-actions"><button class="secondary" data-action="publisher-book" data-id="${esc(book.id)}">${icon('edit')}<span>${tr('Update','Perbarui')}</span></button><button class="publisher-download" data-action="publisher-download" data-id="${esc(book.id)}" aria-label="${esc(tr('Download EPUB: ','Unduh EPUB: ')+book.title)}">${icon('download')}<span>EPUB</span></button></div></article>`).join(''):`<div class="publisher-empty">${icon('bookOpen')}<p>${tr('Upload your first EPUB to begin.','Unggah EPUB pertamamu untuk memulai.')}</p></div>`}</div></section><p class="publisher-hint publisher-download-note">${icon('info')}<span>${tr('Publisher EPUB downloads include unpublished chapters.','Unduhan EPUB publisher mencakup bab yang belum terbit.')}</span></p></section>`;}
 function editor(){const book=draft.book;return `<form id="publisher-plan-form" class="publisher-form" novalidate><div class="glass publisher-card"><h2>${icon('bookOpen')}${draft.isNew?tr('New book','Buku baru'):esc(book.title)}</h2><div class="publisher-fields"><label>${tr('Title','Judul')}<input id="pub-title" value="${esc(book.title)}" maxlength="300"></label><label>${tr('Author','Penulis')}<input id="pub-author" value="${esc(book.author)}" maxlength="300"></label><label>${tr('Story status','Status cerita')}<select id="pub-status"><option value="ongoing" ${book.status!=='completed'?'selected':''}>${tr('Ongoing','Bersambung')}</option><option value="completed" ${book.status==='completed'?'selected':''}>${tr('Completed','Tamat')}</option></select></label><label class="publisher-check"><input id="pub-public" type="checkbox" ${book.is_published?'checked':''}>${tr('Publish in the library','Terbitkan di Library')}</label></div><p class="publisher-hint">${tr('Completed stories publish in full. Existing release dates stay unchanged for ongoing updates.','Cerita tamat diterbitkan utuh. Jadwal lama tetap dipertahankan saat memperbarui cerita bersambung.')}</p></div><div class="glass publisher-card publisher-fields" id="publisher-schedule" ${book.status==='completed'?'hidden':''}><h2>${icon('clock')}${tr('Release schedule','Jadwal rilis')}</h2><label>${tr('New episodes to publish now','Episode baru yang terbit sekarang')}<input id="pub-first" type="number" min="0" max="600" value="${esc(draft.release?.first??'1')}"></label><label>${tr('Following release','Rilis berikutnya')}<input id="pub-start" type="datetime-local" value="${esc(draft.release?.start||nextDate())}"></label><label>${tr('Days between releases','Jarak rilis (hari)')}<input id="pub-interval" type="number" min="1" max="365" value="${esc(draft.release?.interval||'1')}"></label></div><div class="glass publisher-card"><h2>${icon('edit')}${tr('Chapters and updates','Bab dan pembaruan')}</h2><div class="publisher-inline"><button class="secondary" type="button" data-action="publisher-update-file">${icon('upload')}${tr('Import update','Impor pembaruan')}</button><button class="secondary" type="button" data-action="publisher-download" data-id="${esc(book.id)}" ${draft.isNew?'disabled':''}>${icon('download')}EPUB</button></div><p class="publisher-hint">TXT · MD · HTML · EPUB</p><div class="publisher-parts">${parts.map((part,index)=>`<div class="publisher-part"><label>${tr('Chapter','Bab')} ${index+1}<input data-pub-title="${index}" value="${esc(part.title)}" maxlength="300"></label><label>${tr('Action','Tindakan')}<select data-pub-target="${index}"><option value="?" ${part.target==='?'?'selected':''} disabled>${tr('Choose a target','Pilih tujuan')}</option><option value="new" ${part.target==='new'?'selected':''}>${tr('Add new','Tambah baru')}</option><option value="skip" ${part.target==='skip'?'selected':''}>${tr('Skip / unchanged','Lewati / tidak berubah')}</option>${draft.sections.map(s=>`<option value="${s.id}" ${part.target===s.id?'selected':''}>${esc(tr('Replace: ','Ganti: ')+s.title)}</option>`).join('')}</select></label></div>`).join('')||`<p>${tr('Choose an update file to add or replace chapters.','Pilih berkas pembaruan untuk menambah atau mengganti bab.')}</p>`}</div></div><div class="publisher-inline"><button class="secondary" type="button" data-action="publisher-cancel">${tr('Back to books','Kembali ke buku')}</button><button class="primary" type="submit">${icon('check')}${tr('Review changes','Tinjau perubahan')}</button></div></form>`;}
 function passwordView(){return `<form id="publisher-password-form" class="glass publisher-card publisher-form" novalidate><h2>${icon('lock')}${tr('Set a new password','Atur kata sandi baru')}</h2><label>${tr('New password','Kata sandi baru')}<input id="publisher-new-password" type="password" autocomplete="new-password" minlength="8"></label><button class="primary">${tr('Save password','Simpan kata sandi')}</button></form>`;}
 function render(){if(!ctx.active())return;ctx.mount(`<header class="settings-header"><div class="header-brand-space" aria-hidden="true"></div><div class="settings-title-row"><h1>Publisher</h1><button class="header-back" data-action="settings">${icon('left')}<span>${tr('Settings','Pengaturan')}</span></button></div></header><div class="settings-content publisher-content" data-publisher-view="${!signedIn?'login':recovery?'password':draft?'editor':'dashboard'}"><div id="publisher-message" class="publisher-message" role="status" hidden><span class="publisher-message-symbol" aria-hidden="true">${icon('info')}</span><span class="publisher-message-text"></span></div>${!signedIn?loginView():recovery?passwordView():draft?editor():dashboard()}<input type="file" id="publisher-epub-file" accept=".epub,application/epub+zip" hidden><input type="file" id="publisher-update-files" accept=".txt,.md,.markdown,.html,.htm,.xhtml,.epub" multiple hidden></div>`);}
 async function run(work){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('.publisher-content button:not(:disabled),.dialog [data-action=publisher-confirm]')];buttons.forEach(b=>b.disabled=true);$('.publisher-content')?.setAttribute('aria-busy','true');try{await work();}catch(error){msg(error.message||'Publisher request failed.',true);ctx.toast(error.message||'Publisher request failed.');}finally{busy=false;buttons.forEach(b=>b.disabled=false);$('.publisher-content')?.removeAttribute('aria-busy');}}
 async function list(){books=(await api.request('list')).books||[];render();}
 async function openBook(id){const data=await api.request('book',{id}),h=await helpers();const last=Math.max(0,...data.sections.filter(s=>s.is_enabled).map(s=>Date.parse(s.release_at)||0)),next=last>Date.now()?new Date(last+86400000):null;draft={book:data.book,originalBook:{...data.book},sections:data.sections.map(s=>({...s,kind:h.sectionKind(s,data.book)})),release:{first:next?'0':'1',interval:'1',start:next?new Date(next-next.getTimezoneOffset()*60000).toISOString().slice(0,16):nextDate()},isNew:false,sourceFile:null,cover:null};parts=[];prepared=null;render();}
 function capture(){if(!draft||!$('#pub-title'))return;draft.release={first:$('#pub-first').value,start:$('#pub-start').value,interval:$('#pub-interval').value};draft.book={...draft.book,title:$('#pub-title').value.trim(),author:$('#pub-author').value.trim(),status:$('#pub-status').value,is_published:$('#pub-public').checked};parts.forEach((p,i)=>{p.title=$(`[data-pub-title="${i}"]`).value.trim();p.target=$(`[data-pub-target="${i}"]`).value;});}
 async function importEpub(file){const h=await helpers(),data=await h.importPublisherEpub(file),matches=books.filter(b=>h.normalizedTitle(b.title)===h.normalizedTitle(data.title));if(matches.length>1)throw Error('Several books share that title. Open the correct book and import the update there.');const existing=matches[0];if(existing){await openBook(existing.id);parts=h.matchUpdates(data.parts,draft.sections);draft.sourceFile=file;draft.cover=data.cover;}else{
  const id=(data.title.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,85)||'book')+'-'+crypto.randomUUID().slice(0,8);
  const book={...emptyBook(),id,title:data.title,author:data.author,language:data.language};draft={book,sections:[{id:crypto.randomUUID(),title:'Halaman Judul',content_html:`<section class="title-panel" epub:type="titlepage"><h1>${esc(book.title)}</h1><p>${esc(book.author)}</p></section>`,kind:'page',is_enabled:true,release_at:null}],isNew:true,sourceFile:file,cover:data.cover};parts=data.parts.map(p=>({...p,target:'new'}));
 }render();msg(tr('Import ready. Review chapters and release settings before publishing.','Impor siap. Tinjau bab dan pengaturan rilis sebelum menerbitkan.'));}
 async function review(){capture();if(draft.isNew){draft.sections[0].content_html=`<section class="title-panel" epub:type="titlepage"><h1>${esc(draft.book.title)}</h1><p>${esc(draft.book.author)}</p></section>`;}if(!draft.book.title||!draft.book.author)throw Error(tr('Enter a title and author.','Isi judul dan penulis.'));const h=await helpers();prepared=h.planPublication(draft.book,draft.sections,parts,{first:Number($('#pub-first').value),interval:Number($('#pub-interval').value),start:$('#pub-start').value});const metadataChanged=draft.originalBook&&['title','author','status','is_published'].some(key=>draft.book[key]!==draft.originalBook[key]);if(!prepared.changed.length&&!draft.isNew&&!metadataChanged&&!draft.cover)throw Error(tr('No chapter changes selected.','Belum ada perubahan bab yang dipilih.'));
  ctx.show(`${ctx.heading(tr('Publish changes?','Terbitkan perubahan?'))}<p class="dialog-caption">${esc(prepared.book.title)} · ${prepared.book.status==='completed'?tr('Publish the complete story','Terbitkan cerita utuh'):tr('Keep existing release dates','Pertahankan jadwal lama')}</p><div class="publisher-review">${metadataChanged?`<p>${tr('Book details updated.','Informasi buku diperbarui.')}</p>`:''}${prepared.changed.map(change=>`<p><strong>${change.action==='add'?tr('Add','Tambah'):tr('Replace','Ganti')}</strong> ${esc(change.title)}<small>${esc(new Date(prepared.sections.find(s=>s.id===change.id).release_at).toLocaleString(ctx.language()==='id'?'id-ID':'en-GB'))}</small></p>`).join('')}</div><p class="publisher-hint">${prepared.book.is_published?tr('The published episodes will appear in the library.','Episode yang terbit akan muncul di Library.'):tr('This book remains a draft.','Buku ini tetap menjadi draf.')}</p><div class="dialog-actions"><button class="secondary" data-action="close">${tr('Cancel','Batal')}</button><button class="primary" data-action="publisher-confirm">${tr('Apply changes','Terapkan perubahan')}</button></div>`);
 }
 async function publish(){if(!prepared)return;let cover=prepared.book.cover_url;
  if(draft.cover)cover=(await api.request('cover',{id:prepared.book.id,body:draft.cover,mime:draft.cover.type})).url;
  else if(cover?.startsWith('data:image/')){const blob=await(await fetch(cover)).blob();cover=(await api.request('cover',{id:prepared.book.id,body:blob,mime:blob.type})).url;}
  if(draft.sourceFile)await api.request('source',{id:prepared.book.id,body:draft.sourceFile,mime:'application/epub+zip'});
  const payload={book:{...prepared.book,cover_url:cover},sections:prepared.sections,kinds:prepared.kinds,expected_updated_at:draft.isNew?null:draft.book.updated_at};
  payload.request_id=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(payload))))).map(n=>n.toString(16).padStart(2,'0')).join('');
  const result=await api.request('publish',{body:payload});if(ctx.active())ctx.close();draft=null;parts=[];prepared=null;await list();msg(result.archive_ready?tr('Published. The EPUB has been updated.','Diterbitkan. EPUB sudah diperbarui.'):tr('Published. EPUB download is available; the archive can be retried.','Diterbitkan. EPUB dapat diunduh; arsip dapat dicoba ulang.'));ctx.updated();
 }
 function credentials(){const email=$('#publisher-email').value.trim(),password=$('#publisher-password').value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error(tr('Enter a valid email.','Isi email yang valid.'));return {email,password};}
 return{
  async open(){render();await run(async()=>{signedIn=await api.resume();if(signedIn)await list();});},
  action(button){const action=button.dataset.action;if(!action.startsWith('publisher-'))return false;
   if(action==='publisher-toggle-password'){const input=document.getElementById(button.dataset.for),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?tr('Hide password','Sembunyikan kata sandi'):tr('Show password','Tampilkan kata sandi'));button.innerHTML=publisherIcon(show?'eyeOff':'eye');return true;}
   if(action==='publisher-upload'){$('#publisher-epub-file').click();return true;}
   if(action==='publisher-update-file'){$('#publisher-update-files').click();return true;}
   void run(async()=>{switch(action){
    case 'publisher-refresh':await list();break;
    case 'publisher-logout':await api.logout();signedIn=false;draft=null;parts=[];render();break;
    case 'publisher-book':await openBook(button.dataset.id);break;
    case 'publisher-cancel':draft=null;parts=[];render();break;
    case 'publisher-confirm':await publish();break;
    case 'publisher-download':{const blob=await api.request('download',{id:button.dataset.id});if(await ctx.saveFile(button.dataset.id+'.epub',blob))msg(tr('EPUB downloaded.','EPUB diunduh.'));break;}
    case 'publisher-signup':{const {email,password}=credentials();if(password.length<8)throw Error(tr('Use at least 8 characters for your password.','Kata sandi minimal 8 karakter.'));await api.signup(email,password);$('#publisher-password').value='';msg(tr('Check your email to verify the account, then return here to sign in.','Periksa email untuk verifikasi akun, lalu kembali ke sini untuk masuk.'));break;}
    case 'publisher-recover':{const {email}=credentials();await api.recover(email);msg(tr('Check your email for the password reset link.','Periksa email untuk tautan pengaturan ulang kata sandi.'));break;}
   }});return true;
  },
  change(el){if(el.id==='pub-status'){$('#publisher-schedule').hidden=el.value==='completed';return true;}if(!['publisher-epub-file','publisher-update-files'].includes(el.id))return false;const files=[...(el.files||[])];if(!files.length)return true;void run(async()=>{if(el.id==='publisher-epub-file')await importEpub(files[0]);else{capture();const h=await helpers(),incoming=[];for(const file of files){if(/\.epub$/i.test(file.name)){const data=await h.importPublisherEpub(file);incoming.push(...data.parts);draft.sourceFile=file;if(data.cover)draft.cover=data.cover;}else incoming.push(...await h.importChapterFile(file));}parts=h.matchUpdates(incoming,draft.sections);render();msg(tr('Update ready. Check every replacement before applying.','Pembaruan siap. Periksa setiap penggantian sebelum menerapkan.'));}});return true;},
  submit(event){if(!['publisher-login-form','publisher-key-form','publisher-plan-form','publisher-password-form'].includes(event.target.id))return false;event.preventDefault();void run(async()=>{
   if(event.target.id==='publisher-plan-form'){await review();return;}
   if(event.target.id==='publisher-password-form'){const value=$('#publisher-new-password').value;if(value.length<8)throw Error('Use at least 8 characters.');await api.updatePassword(value);recovery=false;await list();return;}
   if(event.target.id==='publisher-key-form')await api.loginKey($('#publisher-key').value);else{const {email,password}=credentials();await api.login(email,password);}signedIn=true;await list();
  });return true;},
 };
}
